diff --git a/kded/firewallzonemonitor.cpp b/kded/firewallzonemonitor.cpp
new file mode 100644
index 000000000..74fc4d3e5
--- /dev/null
+++ b/kded/firewallzonemonitor.cpp
@@ -0,0 +1,134 @@
+/*
+    SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+
+    SPDX-License-Identifier: GPL-2.0-only OR GPL-3.0-only OR LicenseRef-KDE-Accepted-GPL
+*/
+
+#include "firewallzonemonitor.h"
+
+#include <QDBusConnection>
+#include <QDBusMessage>
+#include <QDBusReply>
+
+#include <KLocalizedString>
+
+#include <NetworkManagerQt/Manager>
+#include <NetworkManagerQt/Settings>
+
+#include <QCoroDBus>
+
+#include "plasma_nm_kded.h"
+
+FirewallZoneMonitor::FirewallZoneMonitor(QObject *parent)
+    : QObject(parent)
+{
+    for (const NetworkManager::ActiveConnection::Ptr &ac : NetworkManager::activeConnections()) {
+        addActiveConnection(ac);
+    }
+
+    connect(NetworkManager::notifier(),
+            &NetworkManager::Notifier::activeConnectionAdded,
+            this,
+            QOverload<const QString &>::of(&FirewallZoneMonitor::addActiveConnection));
+}
+
+void FirewallZoneMonitor::addActiveConnection(const QString &path)
+{
+    NetworkManager::ActiveConnection::Ptr ac = NetworkManager::findActiveConnection(path);
+    if (ac && ac->isValid()) {
+        addActiveConnection(ac);
+    }
+}
+
+void FirewallZoneMonitor::addActiveConnection(const NetworkManager::ActiveConnection::Ptr &ac)
+{
+    if (ac->type() != NetworkManager::ConnectionSettings::Wired && ac->type() != NetworkManager::ConnectionSettings::Wireless) {
+        return;
+    }
+
+    const QString path = ac->path();
+    const QString uuid = ac->uuid();
+    connect(ac.data(), &NetworkManager::ActiveConnection::stateChanged, this, [this, path, uuid](NetworkManager::ActiveConnection::State state) {
+        if (state == NetworkManager::ActiveConnection::Activated) {
+            NetworkManager::ActiveConnection::Ptr ac = NetworkManager::findActiveConnection(path);
+            if (ac) {
+                askForZone(ac);
+            }
+        } else if (state == NetworkManager::ActiveConnection::Deactivating || state == NetworkManager::ActiveConnection::Deactivated) {
+            if (KNotification *notification = m_notifications.value(uuid)) {
+                notification->close();
+            }
+        }
+    });
+
+    if (ac->state() == NetworkManager::ActiveConnection::Activated) {
+        askForZone(ac);
+    }
+}
+
+QCoro::Task<> FirewallZoneMonitor::askForZone(NetworkManager::ActiveConnection::Ptr ac)
+{
+    const NetworkManager::Connection::Ptr connection = ac->connection();
+    if (!connection || !connection->settings()->zone().isEmpty() || m_notifications.value(connection->uuid())) {
+        co_return;
+    }
+
+    // Only zone-based firewalls can do something with the answer
+    const QDBusMessage msg = QDBusMessage::createMethodCall(QStringLiteral("org.fedoraproject.FirewallD1"),
+                                                            QStringLiteral("/org/fedoraproject/FirewallD1"),
+                                                            QStringLiteral("org.fedoraproject.FirewallD1.zone"),
+                                                            QStringLiteral("getZones"));
+    const QDBusReply<QStringList> zones = co_await QDBusConnection::systemBus().asyncCall(msg);
+    if (!zones.isValid() || !zones.value().contains(QLatin1String("home")) || !zones.value().contains(QLatin1String("public"))) {
+        co_return;
+    }
+
+    const QString uuid = connection->uuid();
+    if (ac->state() != NetworkManager::ActiveConnection::Activated || m_notifications.value(uuid)) {
+        co_return;
+    }
+
+    auto notification = new KNotification(QStringLiteral("FirewallZone"), KNotification::Persistent);
+    notification->setComponentName(QStringLiteral("networkmanagement"));
+    notification->setIconName(QStringLiteral("security-medium"));
+    notification->setTitle(connection->name());
+    notification->setText(
+        i18n("Is this a home or work network? On public networks, like those in cafés and airports, this computer is hidden from other devices."));
+
+    auto homeAction = notification->addAction(i18nc("@action:button network type", "Home or Work"));
+    connect(homeAction, &KNotificationAction::activated, this, [this, uuid]() {
+        setZone(uuid, QStringLiteral("home"));
+    });
+    auto publicAction = notification->addAction(i18nc("@action:button network type", "Public"));
+    connect(publicAction, &KNotificationAction::activated, this, [this, uuid]() {
+        setZone(uuid, QStringLiteral("public"));
+    });
+
+    m_notifications.insert(uuid, notification);
+    notification->sendEvent();
+}
+
+QCoro::Task<> FirewallZoneMonitor::setZone(const QString &uuid, const QString &zone)
+{
+    const NetworkManager::Connection::Ptr connection = NetworkManager::findConnectionByUuid(uuid);
+    if (!connection) {
+        co_return;
+    }
+
+    NetworkManager::ConnectionSettings settings(connection->settings());
+    settings.setZone(zone);
+
+    const QDBusReply<void> reply = co_await connection->update(settings.toMap());
+    if (!reply.isValid()) {
+        qCWarning(PLASMA_NM_KDED_LOG) << "Failed to set firewall zone of" << connection->name() << reply.error().message();
+
+        auto notification = new KNotification(QStringLiteral("FailedToUpdateConnection"), KNotification::CloseOnTimeout);
+        notification->setComponentName(QStringLiteral("networkmanagement"));
+        notification->setTitle(i18n("Failed to update connection %1", connection->name()));
+        notification->setText(reply.error().message());
+        notification->setIconName(QStringLiteral("dialog-warning"));
+        notification->sendEvent();
+    }
+}
+
+#include "moc_firewallzonemonitor.cpp"
